<?php
/**
 * Nahian POS Menu Item Delete Handler
 *
 * @package NRTOK_POS
 * @since   1.0.0
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( isset( $_GET['del_item'] ) ) {
	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'You do not have sufficient permissions to perform this action.', 'nahian-restaurant-ordering-system' ) );
	}

	$item_id = absint( $_GET['del_item'] );
	if ( $item_id > 0 ) {
		// Verify CSRF nonce generated by wp_nonce_url() in item-list.php & item-view.php.
		check_admin_referer( 'nrtok_delete_item_' . $item_id );

		global $wpdb;
		$t_menu    = $wpdb->prefix . 'nrtok_menu';
		$svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

		// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
		if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $t_menu ) ) === $t_menu ) {
			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
			$deleted = $wpdb->delete(
				$t_menu,
				array( 'id' => $item_id ),
				array( '%d' )
			);

			if ( false !== $deleted && $deleted > 0 ) {
				echo '<div class="nrtok-alert nrtok-itm-alert-flex">' . $svg_check . '<span>' . sprintf( // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
					/* translators: %d: item ID */
					esc_html__( 'Dish #%d deleted successfully!', 'nahian-restaurant-ordering-system' ),
					absint( $item_id )
				) . '</span></div>';
			} else {
				echo '<div class="nrtok-alert" style="background:#fef2f2; border-color:#fecaca; color:#b91c1c;">' . esc_html__( 'Dish could not be deleted or was already removed.', 'nahian-restaurant-ordering-system' ) . '</div>';
			}
		}
	}
}